{
  "categoryId": "{{catId}}",
  "listingType": "SELL",
  "version": 1,
  "isActive": true,
  "title": {
    "en": "List Pesticide",
    "hi": "कीटनाशक सूचीबद्ध करें"
  },
  "fields": [
    {
      "fieldKey": "pesticideCategory",
      "type": "DROPDOWN",
      "label": {
        "en": "Pesticide Category",
        "hi": "कीटनाशक श्रेणी"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 10,
      "optionSetKey": "pesticide__pesticide_category",
      "editableOnUpdate": false
    },
    {
      "fieldKey": "pesticideName",
      "type": "TEXT",
      "label": {
        "en": "Pesticide Name",
        "hi": "कीटनाशक का नाम"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 20,
      "fieldLength": 100,
      "editableOnUpdate": false,
      "validation": {
        "maxLength": 100
      }
    },
    {
      "fieldKey": "pesticideDescription",
      "type": "TEXTAREA",
      "label": {
        "en": "Pesticide Description",
        "hi": "कीटनाशक विवरण"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 30,
      "fieldLength": 1000,
      "inlineEditable": true,
      "validation": {
        "maxLength": 1000
      }
    },
    {
      "fieldKey": "pesticideUsage",
      "type": "TEXT",
      "label": {
        "en": "Pesticide Usage",
        "hi": "कीटनाशक उपयोग"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 40,
      "fieldLength": 120,
      "validation": {
        "maxLength": 120
      }
    },
    {
      "fieldKey": "pesticideUsedFor",
      "type": "TEXT",
      "label": {
        "en": "Used For (Disease / Pest)",
        "hi": "किस रोग / कीट के लिए"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 50,
      "fieldLength": 150,
      "validation": {
        "maxLength": 150
      }
    },
    {
      "fieldKey": "pesticideType",
      "type": "RADIO",
      "label": {
        "en": "Pesticide Type",
        "hi": "कीटनाशक प्रकार"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 60,
      "optionSetKey": "pesticide__pesticide_type"
    },
    {
      "fieldKey": "pesticideBrand",
      "type": "TEXT",
      "label": {
        "en": "Pesticide Brand",
        "hi": "कीटनाशक ब्रांड"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 70,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      }
    },
    {
      "fieldKey": "qty",
      "type": "NUMBER",
      "label": {
        "en": "Quantity",
        "hi": "मात्रा"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": true,
      "displayOrder": 80,
      "inlineEditable": true,
      "validation": {
        "min": 1
      }
    },
    {
      "fieldKey": "qtyMeasurement",
      "type": "DROPDOWN",
      "label": {
        "en": "Unit",
        "hi": "इकाई"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": true,
      "displayOrder": 90,
      "optionSetKey": "pesticide__pesticide_unit",
      "parentField": "pesticideType"
    },
